/**
 * Server-enriched metadata added to all messages by Nchan.
 * This is the absolute source of truth for timing.
 */
export interface Meta {
    ts: number;
    ua: string;
    ip: string;
    origin: string;
    method: string;
    country: string;
    version?: string;
    msgId?: string;
}
/**
 * Seek object for table seeking in the lobby
 */
export interface Seek {
    tableId: string;
    ruleType?: string;
}
/**
 * Presence-related messages (user join/leave/heartbeat)
 */
export interface PresenceMessage {
    messageType: "presence";
    type: "join" | "heartbeat" | "leave";
    userId: string;
    userName: string;
    ruleType?: string;
    opponentId?: string | null;
    seek?: Seek;
    meta?: Meta;
    tableId?: string;
    arenaId?: string;
    isSpectator?: boolean;
    isLeaving?: boolean;
    readonly options?: Record<string, string>;
    custom?: Record<string, unknown>;
}
/**
 * Peer-to-peer challenge request
 */
export interface ChallengeMessage {
    messageType: "challenge";
    type: "offer" | "accept" | "decline" | "cancel";
    challengerId: string;
    challengerName: string;
    challengeeId: string;
    ruleType: string;
    tableId?: string;
    readonly options?: Record<string, string>;
    custom?: Record<string, unknown>;
    nextTurnId?: string;
    meta?: Meta;
}
/**
 * 1-to-1 public-broadcast chat message
 */
export interface ChatMessage {
    messageType: "chat";
    senderId: string;
    recipientId: string;
    text: string;
    meta?: Meta;
}
/**
 * Generic structure for table/game events
 */
export interface TableMessage<T = unknown> {
    type: string;
    senderId: string;
    data: T;
    meta?: Meta;
}
/** Payload for table:leave system messages */
export interface TableLeaveData {
    isSpectator?: boolean;
}
export declare function isSpectatorTableLeave(msg: TableMessage): boolean;
/**
 * Lobby-level information about an active game table
 */
export interface TableInfo {
    tableId: string;
    ruleType: string;
    players: {
        id: string;
        name: string;
    }[];
    spectatorCount: number;
    status: "waiting" | "playing" | "finished";
    createdAt: number;
}
/**
 * Derived active game from presence list
 */
export interface ActiveGame {
    tableId: string;
    players: {
        id: string;
        name: string;
    }[];
    ruleType?: string;
}
/**
 * Union type for messages received via the lobby channel
 */
export type LobbyIncomingMessage = PresenceMessage | ChallengeMessage | ChatMessage;
/**
 * Type guards
 */
export declare function isPresenceMessage(msg: any): msg is PresenceMessage;
export declare function isChallengeMessage(msg: any): msg is ChallengeMessage;
export declare function isChatMessage(msg: any): msg is ChatMessage;
/**
 * Predicate: can the current user challenge this target?
 * Returns true if target is not self, not in a game, and not seeking
 */
export declare function canChallenge(target: PresenceMessage, currentUserId: string): boolean;
/**
 * Predicate: can the current user spectate this target's game?
 * Returns true if target is a player (not spectator) at a different table
 */
export declare function canSpectate(target: PresenceMessage, currentTableId?: string): boolean;
/**
 * Derived status of a user based on their presence state
 */
export type UserStatus = "available" | "playing" | "spectating";
export declare function userStatus(user: PresenceMessage): UserStatus;
/**
 * Predicate: is the user in the lobby (not in a game or spectating)?
 */
export declare function isInLobby(user: PresenceMessage): boolean;
/**
 * Filter: derive active games from presence list
 * Returns unique games (one entry per tableId) with their players
 */
export declare function activeGames(users: PresenceMessage[]): ActiveGame[];
/**
 * Helper to parse incoming Nchan JSON strings
 */
export declare function parseMessage<T>(data: string): T | null;
